3	/**
4	 * The owner's region-and-hash identity. The customerCode is formatted {@code <REGION>-<HASH8>} where
5	 * REGION is the region derived from the owner's postcode (see {@link Locality}) and HASH8 is the first
6	 * eight upper-case hex characters of SHA-256 over the normalized telephone concatenated with the last
7	 * name (see {@link Sha256}). The identity carries no per-owner sequence, so it does not depend on other
8	 * owners; the same telephone and last name always yield the same hash. Every value derived from the
9	 * customerCode — the membership number and its check digit, the create audit record and the locality —
10	 * therefore shares this single identity. Pure functions, so exposed as plain helpers.
11	 */
12	public final class CustomerCode {
13	
14	    /** Number of hex characters in the hash portion of the code. */
15	    private static final int HASH_LENGTH = 8;
16	
17	    private CustomerCode() {
18	    }
19	
20	    /**
21	     * Builds the customerCode {@code <region>-<HASH8>}. The hash is taken over the normalized telephone
22	     * followed by the last name; a {@code null} part contributes an empty string.
23	     */
24	    public static String of(String region, String normalizedTelephone, String lastName) {
25	        return region + "-" + Sha256.prefix(orEmpty(normalizedTelephone) + orEmpty(lastName), HASH_LENGTH);
26	    }
27	
28	    /** The region portion (before the first '-') of a customerCode, or {@code null} when absent. */
29	    public static String regionOf(String customerCode) {
30	        if (customerCode == null) {
31	            return null;
32	        }
33	        int dash = customerCode.indexOf('-');
34	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
35	    }
36	
37	    private static String orEmpty(String value) {
38	        return value == null ? "" : value;
39	    }
40	}
